import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import { useMemo } from "react";
import { Text, View, type ViewProps } from "react-native";
import { Button } from "@/components/nyc-tron/ui/components/Button";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { cellAddress, rangeAddress, type SheetRange } from "@/components/nyc-tron/ui/components/forge/sheet-window";
import { parseA1Range } from "@/components/nyc-tron/ui/components/forge/spreadsheet/chart-model";
import { PanelCheckbox, PanelChoices, PanelField, PanelHeading } from "@/components/nyc-tron/ui/components/forge/spreadsheet/panel-controls";
import { Sparkline } from "@/components/nyc-tron/ui/components/forge/spreadsheet/Sparkline";
import { SPARKLINE_KINDS, sparklineSpecProblem, type SparklineKind, type SparklineSpec } from "@/components/nyc-tron/ui/components/forge/spreadsheet/sparkline-model";

/**
 * Controlled sparkline editor: type, data range, target cell, high/low and
 * negative markers, axis minimum and a live preview from the cells the app
 * passes for `spec.dataRange`. Saving is the app's `onApply`; without it there
 * is no apply button.
 */
export interface SparklineEditorProps extends Omit<ViewProps, "children">,ScopedControlProps {
  readonly spec: SparklineSpec;
  readonly onSpecChange: (spec: SparklineSpec) => void;
  readonly cells: Readonly<Record<string, { readonly computed: string | number | boolean | null } | undefined>>;
  /** Adds "Use selection" for the data range. */
  readonly selection?: SheetRange;
  readonly onApply?: (spec: SparklineSpec) => unknown;
  readonly onRemove?: (spec: SparklineSpec) => unknown;
  readonly disabled?:boolean;
  readonly className?: string;
  readonly unstyled?: boolean;
}

const KIND_LABEL: Record<SparklineKind, string> = { line: "Line", column: "Column", winloss: "Win/loss" };
/** Longest range a sparkline draws, matching a 1-row cell's practical resolution. */
export const MAX_SPARKLINE_VALUES = 512;

/** Values along a one-row or one-column range, in order. */
export function sparklineValues(range: SheetRange, cells: SparklineEditorProps["cells"]): (number | undefined)[] {
  const out: (number | undefined)[] = [];
  const along = range.startRow === range.endRow;
  const from = along ? range.startColumn : range.startRow;
  const to = Math.min(along ? range.endColumn : range.endRow, from + MAX_SPARKLINE_VALUES - 1);
  for (let i = from; i <= to; i++) {
    const v = cells[along ? cellAddress(range.startRow, i) : cellAddress(i, range.startColumn)]?.computed;
    out.push(typeof v === "number" && Number.isFinite(v) ? v : undefined);
  }
  return out;
}

export function SparklineEditor({scope='SparklineEditor',revision=0,...props}:SparklineEditorProps){
 const identity=JSON.stringify(controlIdentity(scope,revision)),owner=JSON.stringify([identity,props.disabled,props.disabledReason]),guard=useScopedControl(owner,props,!!props.disabled||props.disabledReason!==undefined);
 return <SparklineEditorBody key={identity} {...props} actionError={guard.error} disabled={!!props.disabled||props.disabledReason!==undefined||guard.pending}
  onApply={props.onApply?(...args:Parameters<NonNullable<SparklineEditorProps['onApply']>>)=>guard.run('onApply',h=>h.onApply?.(...args)):undefined}
  onRemove={props.onRemove?(...args:Parameters<NonNullable<SparklineEditorProps['onRemove']>>)=>guard.run('onRemove',h=>h.onRemove?.(...args)):undefined}
  onSpecChange={(...args:Parameters<SparklineEditorProps['onSpecChange']>)=>{guard.current()?.onSpecChange(...args);}}
 />;
}
function SparklineEditorBody({actionError,disabledReason,disabled=false,
  spec, onSpecChange, cells, selection, onApply, onRemove, className, unstyled = false, ...props
}: SparklineEditorProps&{actionError?:string|null}) {
  const set = (patch: Partial<SparklineSpec>) => onSpecChange({ ...spec, ...patch });
  const baseProblem = sparklineSpecProblem(spec, parseA1Range);
  const range = parseA1Range(spec.dataRange);
  const length=range?Math.max(range.endRow-range.startRow+1,range.endColumn-range.startColumn+1):0;
  const problem=baseProblem??(length>MAX_SPARKLINE_VALUES?{field:'dataRange' as const,message:`Use at most ${MAX_SPARKLINE_VALUES} source cells for an in-cell chart`}:undefined);
  const valid = range !== undefined && problem === undefined;
  const values = useMemo(() => (valid ? sparklineValues(range, cells) : []), [valid, range?.startRow, range?.endRow,
    range?.startColumn, range?.endColumn, cells]);
  const numeric = values.filter(v => v !== undefined).length;
  const negativeMatters = spec.kind !== "line";
  const muted = !unstyled ? "text-text-muted" : undefined;
  const selectionIsLine = selection && (selection.startRow === selection.endRow || selection.startColumn === selection.endColumn);

  return <View {...props} {...{ className: joinClasses(!unstyled && "rounded-card border border-border bg-surface-raised", className) }}
    style={[{ padding: 16, gap: 16 }, props.style]}>
    <PanelHeading title="Sparkline" unstyled={unstyled} />
    <PanelChoices disabled={disabled} label="Type" value={spec.kind} unstyled={unstyled}
      choices={SPARKLINE_KINDS.map(kind => ({ value: kind, label: KIND_LABEL[kind] }))}
      onChange={kind => set({ kind })} />
    <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 12, alignItems: "flex-end" }}>
      <PanelField disabled={disabled} label="Data range" value={spec.dataRange} placeholder="B2:M2" unstyled={unstyled}
        error={problem?.field === "dataRange" ? problem.message : undefined}
        onChange={dataRange => set({ dataRange })} />
      {selectionIsLine ? <Button disabled={disabled} title="Use selection" variant="secondary" unstyled={unstyled}
        onPress={() => set({ dataRange: rangeAddress(selection) })} /> : null}
      <PanelField disabled={disabled} label="Show in cell" value={spec.location} placeholder="N2" unstyled={unstyled}
        error={problem?.field === "location" ? problem.message : undefined}
        onChange={location => set({ location })} />
    </View>
    <View>
      <PanelCheckbox disabled={disabled} unstyled={unstyled} label="Mark the high point" checked={spec.showHigh} onChange={showHigh => set({ showHigh })} />
      <PanelCheckbox disabled={disabled} unstyled={unstyled} label="Mark the low point" checked={spec.showLow} onChange={showLow => set({ showLow })} />
      {negativeMatters ? <PanelCheckbox disabled={disabled} unstyled={unstyled} label="Shade negative values" checked={spec.showNegative}
        onChange={showNegative => set({ showNegative })} /> : null}
    </View>
    {spec.kind !== "winloss" ? <PanelChoices disabled={disabled} label="Axis starts at" value={spec.axisMin} unstyled={unstyled}
      choices={[{ value: "auto", label: "Lowest value" }, { value: "zero", label: "Zero" }]}
      onChange={axisMin => set({ axisMin })} /> : null}
    <View style={{ flexDirection: "row", alignItems: "center", gap: 12 }}>
      <View {...{ className: joinClasses(!unstyled && "rounded-control border border-border bg-surface-sunken") }}
        style={{ paddingHorizontal: 8, paddingVertical: 6 }}>
        <Sparkline values={values} kind={spec.kind} width={112} height={28} axisMin={spec.axisMin}
          showHigh={spec.showHigh} showLow={spec.showLow} showNegative={spec.showNegative} unstyled={unstyled} />
      </View>
      <Text accessibilityLiveRegion="polite" {...{ className: muted }} style={{ flexShrink: 1 }}>
        {problem ? "Fix the fields above to see a preview."
          : numeric === 0 ? "No numbers in this range yet."
          : `${numeric} of ${values.length} cells have numbers.`}
      </Text>
    </View>
    {onApply || onRemove ? <View style={{ flexDirection: "row", justifyContent: "flex-end", gap: 8 }}>
      {onRemove ? <Button disabled={disabled} title="Remove sparkline" variant="secondary" unstyled={unstyled} onPress={() => onRemove(spec)} /> : null}
      {onApply ? <Button title="Apply" disabled={disabled||Boolean(problem)} unstyled={unstyled} onPress={() => onApply(spec)} /> : null}
    </View> : null}
    {range && !problem ? <Text {...{ className: muted }} style={{ fontSize: 12 }}>
      {`Draws ${rangeAddress(range)} in ${spec.location.toUpperCase()}.`}
    </Text> : null}
  <ErrorMessage message={actionError??disabledReason} unstyled={unstyled}/></View>;
}

import type { ReactNode } from "react";
import { Pressable, Text, TextInput, View } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";

/**
 * Small controlled inputs the spreadsheet panels share. They are internal to
 * `forge/spreadsheet`; app screens should use their own form kit.
 */

export function PanelCheckbox({ label, checked, onChange, disabled, unstyled }: {
  label: string; checked: boolean; onChange: (next: boolean) => void; disabled?: boolean; unstyled: boolean;
}) {
  return <Pressable role="checkbox" aria-checked={checked} aria-disabled={disabled} disabled={disabled}
    accessibilityLabel={label} onPress={() => onChange(!checked)}
    {...{ className: joinClasses(!unstyled && "rounded-control focus-visible:ring-2 focus-visible:ring-focus",
      !unstyled && disabled && "opacity-50") }}
    style={{ minHeight: 44, flexDirection: "row", alignItems: "center", gap: 10, paddingHorizontal: 4 }}>
    <View aria-hidden {...{ className: joinClasses(!unstyled && "rounded border-2",
      !unstyled && (checked ? "border-primary bg-primary" : "border-text-muted bg-surface-raised")) }}
      style={{ width: 20, height: 20, alignItems: "center", justifyContent: "center" }}>
      {checked ? <View {...{ className: !unstyled ? "border-on-primary" : undefined }}
        style={{ width: 10, height: 6, borderLeftWidth: 2, borderBottomWidth: 2, transform: [{ rotate: "-45deg" }], marginTop: -2 }} /> : null}
    </View>
    <Text {...{ className: !unstyled ? "text-text" : undefined }} style={{ flexShrink: 1 }}>{label}</Text>
  </Pressable>;
}

export interface PanelChoice<T extends string> {
  readonly value: T;
  readonly label: string;
  /** Optional drawn preview shown above the label. */
  readonly glyph?: ReactNode;
}

/** A radio group drawn as a row of chips; with glyphs it is a small gallery. */
export function PanelChoices<T extends string>({ label, value, choices, onChange, disabled, unstyled }: {
  label: string; value: T; choices: readonly PanelChoice<T>[]; onChange: (next: T) => void; disabled?: boolean; unstyled: boolean;
}) {
  return <View role="radiogroup" aria-label={label} style={{ gap: 6 }}>
    <Text {...{ className: !unstyled ? "text-text-muted" : undefined }} style={{ fontSize: 13 }}>{label}</Text>
    <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 8 }}>
      {choices.map(choice => {
        const checked = choice.value === value;
        return <Pressable key={choice.value} role="radio" aria-checked={checked} disabled={disabled}
          accessibilityLabel={choice.label} onPress={() => onChange(choice.value)}
          {...{ className: joinClasses(
            !unstyled && "rounded-control border focus-visible:ring-2 focus-visible:ring-focus",
            !unstyled && (checked ? "border-primary bg-primary/10" : "border-border bg-surface-raised"),
            !unstyled && disabled && "opacity-50") }}
          style={{ minHeight: 44, minWidth: 44, paddingHorizontal: 14, paddingVertical: choice.glyph ? 10 : 0,
            alignItems: "center", justifyContent: "center", gap: 6 }}>
          {choice.glyph ?? null}
          <Text {...{ className: joinClasses(!unstyled && "text-text", checked && "font-semibold") }}>{choice.label}</Text>
        </Pressable>;
      })}
    </View>
  </View>;
}

/** Labeled single-line field; `error` is announced and drawn under it. */
export function PanelField({disabled=false, label, value, onChange, placeholder, error, hint, unstyled, autoCapitalize = "none" }: {
  disabled?:boolean;label: string; value: string; onChange: (next: string) => void; placeholder?: string;
  error?: string; hint?: string; unstyled: boolean; autoCapitalize?: "none" | "sentences";
}) {
  return <View style={{ gap: 4, minWidth: 140, flexGrow: 1, flexBasis: 140 }}>
    <Text {...{ className: !unstyled ? "text-text-muted" : undefined }} style={{ fontSize: 13 }}>{label}</Text>
    <TextInput editable={!disabled} maxLength={8192} value={value} onChangeText={onChange} placeholder={placeholder} accessibilityLabel={label}
      accessibilityHint={hint} autoCapitalize={autoCapitalize} autoCorrect={false} aria-invalid={Boolean(error)}
      {...{ className: joinClasses(!unstyled && "rounded-control border bg-surface-sunken text-text focus:border-focus",
        !unstyled && (error ? "border-danger" : "border-border")) }}
      style={{ minHeight: 44, paddingHorizontal: 10 }} />
    {error ? <Text selectable accessibilityRole="alert" accessibilityLiveRegion="polite"
      {...{ className: !unstyled ? "text-danger" : undefined }} style={{ fontSize: 13 }}>{error}</Text> : null}
  </View>;
}

/** Panel heading row; titles are real headings for screen readers. */
export function PanelHeading({ title, unstyled }: { title: string; unstyled: boolean }) {
  return <Text role="heading" aria-level={3} {...{ className: !unstyled ? "text-text font-semibold" : undefined }}
    style={{ fontSize: 16 }}>{title}</Text>;
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
